files.content:
name: Node SDK v2 compliance

on:
    workflow_dispatch:
    push:
        branches: [main]
        paths:
            - 'packages/node/**'
            - 'packages/core/**'
            - 'packages/types/**'
            - 'tooling/tsconfig-base/**'
            - 'compliance/node/v2/**'
            - '.github/workflows/sdk-compliance-tests-node-v2.yml'
            - '**/package.json'
            - 'pnpm-lock.yaml'
            - 'pnpm-workspace.yaml'
            - '.npmrc'
            - 'patches/**'
            - 'turbo.json'
            - 'LICENSE'
    pull_request:
        paths:
            - 'packages/node/**'
            - 'packages/core/**'
            - 'packages/types/**'
            - 'tooling/tsconfig-base/**'
            - 'compliance/node/v2/**'
            - '.github/workflows/sdk-compliance-tests-node-v2.yml'
            # Frozen workspace installation also checks workspace manifests.
            - '**/package.json'
            - 'pnpm-lock.yaml'
            - 'pnpm-workspace.yaml'
            - '.npmrc'
            - 'patches/**'
            - 'turbo.json'
            - 'LICENSE'

permissions: {}

jobs:
    compliance:
        runs-on: ubuntu-24.04
        # Leave time for bounded startup/cleanup and artifact upload after a timeout.
        timeout-minutes: 85
        # Compliance is advisory; the report is reviewed by a human.
        continue-on-error: true
        permissions:
            contents: read
        strategy:
            fail-fast: false
            matrix:
                mode: [v0, v1]
        defaults:
            run:
                shell: bash
        env:
            NODE_IMAGE: node:24.21.0-bookworm-slim@sha256:0e0ff40c39bc087845bfb27465a0df4ea419520094bc35842ff83dd8cbe6f9b6
            # Harness release 1.10.0; pin the published multi-platform image index.
            HARNESS_IMAGE: ghcr.io/posthog/sdk-test-harness-v2@sha256:0c7516bf9d53760b7333f17ebce5c459e69f46a5e878441226cc72abc513de45
            CAPTURE_MODE: ${{ matrix.mode }}
        steps:
            # Test the PR head or the triggering commit for push/manual runs.
            - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
              id: checkout
              continue-on-error: true
              with:
                  ref: ${{ github.event.pull_request.head.sha || github.sha }}
                  persist-credentials: false
            - name: Validate image pins and build selected source
              id: prepare
              if: steps.checkout.outcome == 'success'
              continue-on-error: true
              timeout-minutes: 20
              run: |
                  mkdir -p "$RUNNER_TEMP/node-compliance"
                  bash compliance/node/v2/prepare-ci.sh "$RUNNER_TEMP/node-compliance" \
                    2>&1 | tee "$RUNNER_TEMP/node-compliance/prepare.log"
            - name: Run isolated compliance profile
              if: steps.prepare.outcome == 'success'
              continue-on-error: true
              timeout-minutes: 35
              run: |
                  bash compliance/node/v2/run-compliance.sh node-compliance:local "$HARNESS_IMAGE" \
                    "$CAPTURE_MODE" "$RUNNER_TEMP/node-compliance/reports" \
                    2>&1 | tee "$RUNNER_TEMP/node-compliance/run.log"
            - name: Run isolated acceptance profile
              if: steps.prepare.outcome == 'success'
              continue-on-error: true
              timeout-minutes: 25
              run: |
                  bash compliance/node/v2/run-compliance.sh node-compliance:local "$HARNESS_IMAGE" \
                    "$CAPTURE_MODE" "$RUNNER_TEMP/node-compliance/acceptance" acceptance \
                    2>&1 | tee "$RUNNER_TEMP/node-compliance/acceptance-run.log"
            - uses: actions/upload-artifact@cf430e030ddbb5b0abf93d22962f4752f3646cd9 # v7.0.2
              if: always()
              continue-on-error: true
              timeout-minutes: 3
              with:
                  name: node-v2-${{ matrix.mode }}
                  path: ${{ runner.temp }}/node-compliance
                  if-no-files-found: error
                  retention-days: 14

    report:
        name: Compliance results (advisory)
        needs: compliance
        if: always()
        concurrency:
            group: node-compliance-report-${{ github.event.pull_request.number || github.run_id }}
            cancel-in-progress: false
        runs-on: ubuntu-24.04
        timeout-minutes: 5
        continue-on-error: true
        permissions:
            actions: read
            pull-requests: write
        steps:
            - uses: step-security/harden-runner@ccd8616d44fd3846e67624a50d5aad6d37bf2d25 # v2.22.1
              with:
                  egress-policy: audit
            - uses: actions/download-artifact@9000827ccba6bdab643e8b6fd33ac0654aef8333 # v8.0.2
              continue-on-error: true
              with:
                  pattern: node-v2-*
                  path: ${{ runner.temp }}/node-compliance-results
            # No checkout or execution of code from the tested revision in this job.
            - name: Summarize results and update PR comment
              continue-on-error: true
              uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
              env:
                  REPORT_ROOT: ${{ runner.temp }}/node-compliance-results
              with:
                  script: |
                      const fs = require('node:fs');
                      const path = require('node:path');
                      const marker = '<!-- posthog-sdk-compliance-report-posthog-node -->';
                      const sha = context.payload.pull_request?.head.sha || context.sha;
                      const runUrl = `${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId}`;
                      // Artifact strings are data, not Markdown, HTML or user mentions. Bound AFTER escaping.
                      const escape = (value, limit = 400) => {
                          let text = '';
                          for (const char of String(value).slice(0, limit)) {
                              const encoded = /[&<>@`*_[\]\\|\r\n]/.test(char) ? `&#${char.charCodeAt(0)};` : char;
                              if (text.length + encoded.length > limit - 1) return text + '…';
                              text += encoded;
                          }
                          return text + (String(value).length > limit ? '…' : '');
                      };
                      const sameSource = (a, b) => a && b && typeof a.path === 'string' && typeof a.revision === 'string' &&
                          Number.isSafeInteger(a.line) && a.line > 0 && ['path', 'line', 'revision'].every(key => a[key] === b[key]);
                      const sourceLabel = (source, distribution) => {
                          if (!source || typeof source.path !== 'string' || !Number.isSafeInteger(source.line) || source.line < 1) return '';
                          const label = escape(`${source.path}:${source.line}`);
                          const commit = distribution?.source?.commit;
                          const segments = source.path.split('/');
                          if (distribution?.source?.dirty !== false || !/^[a-f0-9]{40}$/.test(commit || '') ||
                              source.path.length > 300 || !source.path.endsWith('.feature') ||
                              segments.some(part => !part || part === '.' || part === '..' || /[\\\x00-\x1f\x7f]/.test(part))) return label;
                          // Packaged feature paths are relative to the sdk-specs repository root.
                          const encoded = segments.map(part => encodeURIComponent(part).replace(/[!'()*]/g,
                              char => `%${char.charCodeAt(0).toString(16)}`)).join('/');
                          return `[${label}](https://github.com/PostHog/sdk-specs/blob/${commit}/${encoded}#L${source.line})`;
                      };
                      const json = value => escape(JSON.stringify(value, (key, item) =>
                          /^(api[_-]?key|personal[_-]?api[_-]?key|authorization|cookie|password|secret|token|headers|wire_requests|body_decompressed)$/i.test(key)
                              ? '[redacted]' : item), 1200);
                      const lines = [marker, '# Node SDK compliance v2', '',
                          `Commit: ${sha}`, `[Workflow run and artifacts](${runUrl})`, ''];
                      for (const [mode, profile, suite, reports] of [
                          ['v0', 'node-legacy', 'acceptance', 'acceptance'],
                          ['v1', 'node-analytics-v1', 'acceptance', 'acceptance'],
                          ['v0', 'node-legacy', 'migration', 'reports'],
                          ['v1', 'node-analytics-v1', 'migration', 'reports'],
                      ]) {
                          lines.push(`## Capture ${mode} — ${suite}`, '');
                          try {
                              const root = path.join(process.env.REPORT_ROOT, `node-v2-${mode}`);
                              const read = file => {
                                  const filename = path.join(root, file);
                                  if (fs.statSync(filename).size > 10 * 1024 * 1024) throw new Error('Report file exceeds 10 MiB');
                                  return fs.readFileSync(filename, 'utf8');
                              };
                              if (read('source.txt').trim() !== sha) throw new Error('Artifact source does not match the tested commit');
                              const report = JSON.parse(read(`${reports}/report.json`));
                              if (report.contract_version !== 'sdk-compliance-v2-draft2' ||
                                  !Array.isArray(report.results) || !Array.isArray(report.errors) ||
                                  !report.profiles?.some(p => p.id === profile) ||
                                  report.results.some(r => r.profile_id !== profile || typeof r.result?.status !== 'string')) {
                                  throw new Error('Invalid compliance report');
                              }
                              let diagnostics;
                              try {
                                  const candidate = JSON.parse(read(`${reports}/report.json.diagnostics.json`));
                                  const byId = new Map(report.results.map(r => [r.case_id, r]));
                                  const seen = new Set();
                                  if (byId.size !== report.results.length || typeof report.run_id !== 'string' || !report.run_id || candidate.run_id !== report.run_id ||
                                      !Array.isArray(candidate.cases) || candidate.cases.some(c => {
                                          const result = byId.get(c?.case_id);
                                          const duplicate = seen.has(c?.case_id);
                                          seen.add(c?.case_id);
                                          return !result || duplicate || c.profile_id !== profile || !sameSource(c.source, result.source);
                                      })) throw new Error('Diagnostics do not match the report run/profile/cases');
                                  diagnostics = candidate;
                              } catch {
                                  lines.push('⚠️ Detailed diagnostics unavailable or mismatched; use the report and artifact logs.', '');
                              }
                              const cases = new Map((diagnostics?.cases || []).map(c => [c.case_id, c]));
                              const results = report.results.filter(r => r.result.status !== 'not_selected');
                              const passed = results.filter(r => r.result.status === 'passed' && r.result.executed === true);
                              const failures = results.filter(r => !passed.includes(r));
                              const notSelected = report.results.length - results.length;
                              lines.push(`**✅ ${passed.length} passed / ❌ ${failures.length} non-passing / ⚠️ ${notSelected} not selected**`, '',
                                  `Drill-down: [run artifacts](${runUrl}#artifacts) → <code>node-v2-${mode}</code> → <code>${reports}/report.json.diagnostics.json</code> (match case_id below).`, '');
                              let shown = 0;
                              let detailBudget = 24000;
                              for (const r of failures.slice(0, 20)) {
                                  const failure = r.result.failure;
                                  const diagnostic = cases.get(r.case_id)?.failure;
                                  const attributed = failure && diagnostic && failure.code === diagnostic.code &&
                                      failure.failed_step?.index === diagnostic.failed_step?.index &&
                                      sameSource(failure.failed_step?.source, diagnostic.failed_step?.source) ? diagnostic : undefined;
                                  const detail = ['<details>', `<summary>❌ ${escape(r.case_id)} — ${escape(r.result.status)}</summary>`, '',
                                      escape(failure?.message || r.result.reason || 'No diagnostic message'), ''];
                                  if (failure?.code) detail.push(`Code: <code>${escape(failure.code)}</code>`, '');
                                  const source = sourceLabel(failure?.failed_step?.source, diagnostics?.distribution);
                                  if (source) detail.push(`Failed step: ${source}`, '');
                                  if (attributed?.step_text) detail.push(`<pre>${escape(attributed.step_text, 1200)}</pre>`, '');
                                  // Only assertion-specific fields are published, never complete diagnostics or wire requests.
                                  const values = attributed?.details;
                                  if (values && ['/get_feature_flag', '/flags', '/flags/'].includes(values.operation)) {
                                      detail.push(`Operation: <code>${escape(values.operation)}</code>`, '');
                                      if (values.operation === '/get_feature_flag' && values.arguments && typeof values.arguments === 'object') {
                                          const args = Object.fromEntries(['key', 'distinct_id', 'person_properties', 'groups', 'group_properties',
                                              'only_evaluate_locally', 'send_event', 'disable_geoip'].filter(key => Object.hasOwn(values.arguments, key))
                                              .map(key => [key, values.arguments[key]]));
                                          detail.push(`Arguments:<pre>${json(args)}</pre>`, '');
                                      }
                                      if (['/flags', '/flags/'].includes(values.operation) && typeof values.field === 'string') {
                                          detail.push(`Field: <code>${escape(values.field)}</code>`, '');
                                      }
                                      if (Object.hasOwn(values, 'expected')) detail.push(`Expected:<pre>${json(values.expected)}</pre>`, '');
                                      if (Object.hasOwn(values, 'actual')) {
                                          const actual = values.actual;
                                          if (actual?.kind === 'value' && Object.hasOwn(actual, 'value')) {
                                              detail.push(`Actual value:<pre>${json(actual.value)}</pre>`, '');
                                          } else if (actual?.kind === 'missing') {
                                              detail.push('Actual field: **missing**', '');
                                          } else if (actual?.kind === 'untraversable') {
                                              detail.push(`Actual field: cannot traverse <code>${escape(actual.at)}</code>`, '');
                                          } else if (typeof actual?.kind === 'string') {
                                              detail.push(`Actual outcome: <code>${escape(actual.kind)}</code>`, '');
                                              if (Object.hasOwn(actual, 'error')) detail.push(`Error:<pre>${json(actual.error)}</pre>`, '');
                                          } else {
                                              detail.push(`Actual value:<pre>${json(actual)}</pre>`, '');
                                          }
                                      }
                                  }
                                  detail.push('</details>', '');
                                  const block = detail.join('\n');
                                  const size = Buffer.byteLength(block, 'utf8');
                                  if (size > detailBudget) break;
                                  detailBudget -= size;
                                  lines.push(block);
                                  shown++;
                              }
                              if (failures.length > shown) lines.push(`⚠️ ${failures.length - shown} more non-passing cases; see the artifact.`);
                              for (const error of report.errors.slice(0, 10)) lines.push(`- Harness error: ${escape(JSON.stringify(error))}`);
                              if (report.errors.length > 10) lines.push(`- ${report.errors.length - 10} more harness errors; see the artifact.`);
                              const exit = read(`${reports}/cli-exit.txt`).trim();
                              const validation = read(`${reports}/report-check-exit.txt`).trim();
                              lines.push('', `Harness exit: ${escape(exit)}; report validation exit: ${escape(validation)}.`, '');
                              if (results.length > 0 && !failures.length && !report.errors.length && exit === '0' && validation === '0') {
                                  lines.push('All selected cases passed and report validation succeeded.', '');
                              }
                          } catch (error) {
                              lines.push(`**⚠️ Results unavailable or incomplete:** ${escape(error.message)}.`,
                                  'Inspect preparation, execution and artifact-upload logs in the workflow run.', '');
                          }
                      }
                      // Reserve an explicit total budget, including escaping and UTF-8 expansion.
                      const footer = `\n⚠️ Report truncated; see [workflow artifacts](${runUrl}#artifacts) for complete results.`;
                      let body = '';
                      for (const line of lines) {
                          if (Buffer.byteLength(body + line + '\n' + footer, 'utf8') > 60000) {
                              body += footer;
                              break;
                          }
                          body += line + '\n';
                      }
                      core.info(body);
                      await core.summary.addRaw(body).write();
                      const pr = context.payload.pull_request;
                      if (!pr || pr.head.repo?.full_name !== `${context.repo.owner}/${context.repo.repo}` ||
                          context.actor === 'dependabot[bot]') {
                          core.info('PR comment skipped: this event has no writable same-repository PR. Results are in the job summary.');
                          return;
                      }
                      const { data: current } = await github.rest.pulls.get({ ...context.repo, pull_number: pr.number });
                      if (current.head.sha !== sha) {
                          core.info('PR head changed; keeping these results in the job summary without replacing the current comment.');
                          return;
                      }
                      const comments = await github.paginate(github.rest.issues.listComments,
                          { ...context.repo, issue_number: pr.number, per_page: 100 });
                      const existing = comments.find(c => c.user?.login === 'github-actions[bot]' && c.body?.startsWith(marker));
                      if (existing) {
                          await github.rest.issues.updateComment({ ...context.repo, comment_id: existing.id, body });
                      } else {
                          await github.rest.issues.createComment({ ...context.repo, issue_number: pr.number, body });
                      }

{
    "name": "@posthog-tooling/sdk-mock-server",
    "version": "0.0.0",
    "private": true,
    "type": "module",
    "exports": {
        ".": {
            "types": "./dist/index.d.ts",
            "import": "./dist/index.js"
        }
    },
    "scripts": {
        "build": "tsc -p tsconfig.json",
        "check-types": "tsc -p tsconfig.json --noEmit",
        "test:unit": "node --test tests/*.test.mjs",
        "lint": "oxfmt --check src tests && oxlint -c ../../.oxlintrc.correctness.json src tests"
    },
    "devDependencies": {
        "@types/node": "^22.19.1",
        "typescript": "catalog:native"
    }
}

/* global globalThis, process */
import Config from '../config'

if (process.env.POSTHOG_FUNCTIONAL_TESTS) {
    delete globalThis.fetch
}

const failOnUnexpectedConsoleOutput = () => {
    console.debug = (...args) => {
        throw new Error(`Unexpected console.debug: ${args}`)
    }

    console.error = (...args) => {
        throw new Error(`Unexpected console.error: ${args}`)
    }

    console.info = (...args) => {
        throw new Error(`Unexpected console.info: ${args}`)
    }

    console.log = (...args) => {
        throw new Error(`Unexpected console.log: ${args}`)
    }

    console.warn = (...args) => {
        throw new Error(`Unexpected console.warn: ${args}`)
    }
}

failOnUnexpectedConsoleOutput()

beforeEach(() => {
    Config.DEBUG = false
    if (typeof window !== 'undefined') {
        Reflect.deleteProperty(window, 'POSTHOG_DEBUG')
        try {
            window.localStorage?.removeItem('ph_debug')
        } catch {
            // Some storage tests intentionally replace localStorage with a throwing mock.
        }
    }

    failOnUnexpectedConsoleOutput()

    // Prevent jsdom XHR requests from creating open handles (TLSWRAP/Timeout)
    // that keep unit test workers alive. Functional tests exercise the real XHR transport.
    if (!process.env.POSTHOG_FUNCTIONAL_TESTS && typeof XMLHttpRequest !== 'undefined') {
        vi.spyOn(XMLHttpRequest.prototype, 'send').mockImplementation(() => {})
    }
})

import type { BrowserContext, Page } from '@playwright/test'
import { start, waitForRemoteConfig, waitForSessionRecordingToStart } from '../../playwright/mocked/utils/setup'

describe('Playwright setup helpers', () => {
    it('awaits async hooks before initialization and before returning', async () => {
        const phases: string[] = []
        const page = {
            goto: vi.fn(),
            evaluate: vi.fn(async () => {
                phases.push('initialize')
            }),
        } as unknown as Page
        const context = { route: vi.fn() } as unknown as BrowserContext

        await start(
            {
                waitForFlags: false,
                runBeforePostHogInit: async () => {
                    await Promise.resolve()
                    phases.push('before')
                },
                runAfterPostHogInit: async () => {
                    await Promise.resolve()
                    await Promise.resolve()
                    phases.push('after')
                },
            },
            page,
            context
        )
        phases.push('returned')

        expect(phases).toEqual(['before', 'initialize', 'after', 'returned'])
    })

    it.each([
        ['recording start', waitForSessionRecordingToStart],
        ['remote config', waitForRemoteConfig],
    ] as const)('passes the %s timeout as Playwright options, not as the page argument', async (_, wait) => {
        const waitForFunction = vi.fn()
        const page = { waitForFunction } as unknown as Page

        await wait(page, 123)

        expect(waitForFunction).toHaveBeenCalledWith(expect.any(Function), undefined, { timeout: 123 })
    })
})

import { Page, BrowserContext } from '@playwright/test'
import { Compression, FlagsResponse, PostHogConfig } from '../../../src/types'
import path from 'path'
import { WindowWithPostHog } from './posthog-playwright-test-base'

/**
 * uses the standard playwright page.goto
 * but if the URL starts with './'
 * treats it as a relative file path
 *
 */
export async function gotoPage(page: Page, url: string) {
    // Visit the specified URL
    if (url.startsWith('./')) {
        const filePath = path.resolve(process.cwd(), url)
        // starts with a single slash since otherwise we get three
        url = `file://${filePath}`
    }
    await page.goto(url)
}

export interface StartOptions {
    waitForFlags?: boolean
    initPosthog?: boolean
    resetOnInit?: boolean
    // playwright is stricter than cypress on access to the window object
    // sometimes you need to pass functions here that will run on window in the correct page
    runBeforePostHogInit?: (pg: Page) => void | Promise<void>
    // playwright is stricter than cypress on access to the window object
    // sometimes you need to pass functions here that will run on window in the correct page
    runAfterPostHogInit?: (pg: Page) => void | Promise<void>
    type?: 'navigate' | 'reload'
    options?: Partial<PostHogConfig>
    flagsResponseOverrides?: Partial<FlagsResponse>
    url?: string
}

export async function start(
    {
        waitForFlags = true,
        initPosthog = true,
        resetOnInit = false,
        runBeforePostHogInit = undefined,
        runAfterPostHogInit = undefined,
        type = 'navigate',
        options = {},
        flagsResponseOverrides = {
            sessionRecording: undefined,
            isAuthenticated: false,
            capturePerformance: true,
        },
        url = '/playground/cypress-full/index.html',
    }: StartOptions,
    page: Page,
    context: BrowserContext
) {
    options.opt_out_useragent_filter = true

    // Prepare the mocked Flags API response
    const flagsResponse: FlagsResponse = {
        editorParams: {},
        flags: {
            'session-recording-player': {
                key: '7569-insight-cohorts',
                enabled: true,
                variant: undefined,
                reason: {
                    code: 'condition_match',
                    condition_index: 0,
                    description: 'Matched condition set 1',
                },
                metadata: {
                    id: 1421,
                    version: 1,
                    description: undefined,
                    payload: undefined,
                },
            },
        },
        featureFlags: { 'session-recording-player': true },
        featureFlagPayloads: {},
        errorsWhileComputingFlags: false,
        toolbarParams: {},
        toolbarVersion: 'toolbar',
        isAuthenticated: false,
        siteApps: [],
        supportedCompression: [Compression.GZipJS],
        autocaptureExceptions: false,
        autocapture_opt_out: false,
        ...flagsResponseOverrides,
    }

    // Mock the remote config endpoint to return the same config data as the flags response.
    // RemoteConfig is now the sole config loading mechanism, so tests must serve it.
    // Uses a regex that excludes config.js (script) — only intercepts the JSON config endpoint.
    void context.route(/\/array\/[^/]+\/config(\?|$)/, (route) => {
        route.fulfill({
            status: 200,
            contentType: 'application/json',
            body: JSON.stringify(flagsResponse),
        })
    })

    // allow promise in e2e tests
    const flagsMock = new Promise((resolve) => {
        void context.route('**/flags/*', (route) => {
            route.fulfill({
                status: 200,
                contentType: 'application/json',
                body: JSON.stringify(flagsResponse),
            })
            resolve('mock network to flags was triggered')
        })
    })

    if (type === 'reload') {
        await page.reload()
    } else {
        await gotoPage(page, url)
    }

    await runBeforePostHogInit?.(page)

    // Initialize PostHog if required
    if (initPosthog) {
        await page.evaluate(
            // TS very unhappy with passing PostHogConfig here, so just pass an object
            (posthogOptions: Record<string, any>) => {
                const opts: Partial<PostHogConfig> = {
                    api_host: 'https://localhost:1234',
                    debug: true,
                    ip: false, // Prevent IP deprecation warning in Playwright tests
                    before_send: (event) => {
                        const win = window as WindowWithPostHog
                        win.capturedEvents = win.capturedEvents || []

                        if (event) {
                            win.capturedEvents.push(event)
                        }

                        return event
                    },
                    loaded: (ph) => {
                        if (ph.sessionRecording) {
                            ph.sessionRecording._forceAllowLocalhostNetworkCapture = true
                        }
                        // playwright can't serialize functions to pass around from the playwright to browser context
                        // if we want to run custom code in the loaded function we need to pass it on the page's window,
                        // but it's a new window so we have to create it in the `before_posthog_init` option
                        ;(window as any).__ph_loaded?.(ph)
                    },
                    opt_out_useragent_filter: true,
                    ...posthogOptions,
                }

                const windowPosthog = (window as WindowWithPostHog).posthog
                windowPosthog?.init('test token', opts)
            },
            options as Record<string, any>
        )
    }

    await runAfterPostHogInit?.(page)

    // Reset PostHog if required
    if (resetOnInit) {
        await page.evaluate(() => {
            const windowPosthog = (window as WindowWithPostHog).posthog
            windowPosthog?.reset(true)
        })
    }

    // Wait for `/flags` response if required
    if (waitForFlags) {
        await flagsMock
    }
}

/**
 * Wait for session recording to actually start after remote config is received
 * This is needed because session recording now waits for fresh remote config before starting
 */
export async function waitForSessionRecordingToStart(page: Page, timeout = 5000): Promise<void> {
    await page.waitForFunction(
        () => {
            const ph = (window as any).posthog
            return ph?.sessionRecording?.started === true
        },
        undefined,
        { timeout }
    )
}

/**
 * Wait for remote config to be received and processed
 * Use this when recording might not start due to triggers/sampling, but you need config to be loaded
 * After config is received, status changes from 'lazy_loading' to 'active', 'buffering', or 'disabled'
 */
export async function waitForRemoteConfig(page: Page, timeout = 5000): Promise<void> {
    await page.waitForFunction(
        () => {
            const ph = (window as any).posthog
            const status = ph?.sessionRecording?.status
            return status !== 'lazy_loading' && status !== undefined
        },
        undefined,
        { timeout }
    )
}

