  it('should not create duplicate events when instrument() is called multiple times', async () => {
    const { server, client, cleanup } = await setupTestServerAndClient()

    try {
      await instrument(server, fakePostHog())

      await instrument(server, fakePostHog())

      await instrument(server, fakePostHog())

      await client.request(
        {
          method: 'tools/call',
          params: {
            name: 'add_todo',
            arguments: {
              text: 'Test todo for double-wrapping',
              context: 'Setup for double-wrapping test',
            },
          },
        },
        CallToolResultSchema
      )

      await new Promise((resolve) => setTimeout(resolve, 100))

      eventCapture.clear()

      const result = await client.request(
        {
          method: 'tools/call',
          params: {
            name: 'complete_todo',
            arguments: {
              id: '1',
              context: 'Testing double-wrapping protection',
            },
          },
        },
        CallToolResultSchema
      )

      await new Promise((resolve) => setTimeout(resolve, 100))

      expect(result).toBeDefined()
      expect(result.isError).not.toBe(true)

      const events = eventCapture.getEvents()

      expect(events.length).toBe(1)
      expect(events[0].resourceName).toBe('complete_todo')
      expect(events[0].isError).toBe(false)
      expect(events[0].duration).toEqual(expect.any(Number))
    } finally {
      await cleanup()
    }
  })

  it('should publish events for successful tool calls with handler-level architecture', async () => {
    const { server, client, cleanup } = await setupTestServerAndClient()

    try {
      await instrument(server, fakePostHog())

      const result = await client.request(
        {
          method: 'tools/call',
          params: {
            name: 'add_todo',
            arguments: {
              text: 'Test successful handler wrapping',
              context: 'Testing handler-level event publishing',
            },
          },
        },
        CallToolResultSchema
      )

      await new Promise((resolve) => setTimeout(resolve, 100))

      expect(result).toBeDefined()
      expect(result.isError).not.toBe(true)

      const events = eventCapture.getEvents()

      expect(events.length).toBe(1)
      expect(events[0].resourceName).toBe('add_todo')
      expect(events[0].isError).toBe(false)
      expect(events[0].duration).toEqual(expect.any(Number))
      expect(events[0].userIntent).toBe('Testing handler-level event publishing')

      expect(events[0]).toHaveProperty('eventType')
      expect(events[0]).toHaveProperty('timestamp')
    } finally {
      await cleanup()
    }
  })
})

import { expect, test } from './utils/posthog-playwright-test-base'
import { start } from './utils/setup'
import { Page, BrowserContext, Request } from '@playwright/test'

const baseOptions = {
    options: {
        tracing_headers: ['example.com', 'no-session.com', 'xhr-test.com'],
    },
    url: '/playground/cypress/index.html',
}

async function setupAndTriggerRequest(
    page: Page,
    context: BrowserContext,
    config: {
        domain: string
        method?: 'fetch' | 'xhr'
        startOptions?: typeof baseOptions
    }
): Promise<Record<string, string>> {
    const { domain, method = 'fetch', startOptions = baseOptions } = config
    let capturedHeaders: Record<string, string> | undefined

    page.on('request', (request: Request) => {
        if (request.url().includes(domain)) {
            capturedHeaders = request.headers()
        }
    })

    await context.route(`**/${domain}/**`, (route) => {
        route.fulfill({ status: 200, contentType: 'text/plain', body: 'ok' })
    })

    await start(startOptions, page, context)

    await page.waitForFunction(() => {
        const win = window as any
        return win.__PosthogExtensions__?.tracingHeadersPatchFns && win.posthog
    })

    if (method === 'fetch') {
        const response = await page.evaluate(async (d) => {
            const response = await fetch(`https://${d}/api/test`)
            return { status: response.status, body: await response.text() }
        }, domain)
        expect(response).toEqual({ status: 200, body: 'ok' })
    } else {
        const response = await page.evaluate(
            (d) =>
                new Promise<{ status: number; body: string }>((resolve, reject) => {
                    const xhr = new XMLHttpRequest()
                    xhr.onload = () => resolve({ status: xhr.status, body: xhr.responseText })
                    xhr.onerror = () => reject(new Error('customer XHR failed'))
                    xhr.open('GET', `https://${d}/api/test`)
                    xhr.send()
                }),
            domain
        )
        expect(response).toEqual({ status: 200, body: 'ok' })
    }

    expect(capturedHeaders).toBeDefined()
    return capturedHeaders!
}

test.describe('tracing headers', () => {
    const casesWithHeaders = [
        { name: 'fetch to listed domain', domain: 'example.com' },
        { name: 'fetch with session recording disabled', domain: 'no-session.com', disableSession: true },
    ]

    for (const { name, domain, disableSession } of casesWithHeaders) {
        test(`adds tracing headers: ${name}`, async ({ page, context }) => {
            const startOptions = disableSession
                ? { ...baseOptions, options: { ...baseOptions.options, disable_session_recording: true } }
                : baseOptions

            const headers = await setupAndTriggerRequest(page, context, { domain, startOptions })

            const ids = await page.evaluate(() => {
                const ph = (window as any).posthog
                return { distinctId: ph.get_distinct_id(), ...ph.sessionManager.checkAndGetSessionAndWindowId(true) }
            })
            expect(ids.distinctId).toBeTruthy()
            expect(ids.sessionId).toBeTruthy()
            expect(ids.windowId).toBeTruthy()
            expect(headers['x-posthog-distinct-id']).toBe(ids.distinctId)
            expect(headers['x-posthog-session-id']).toBe(ids.sessionId)
            expect(headers['x-posthog-window-id']).toBe(ids.windowId)
        })
    }

    const casesWithoutHeaders = [
        { name: 'fetch to unlisted domain', domain: 'unlisted.com', method: 'fetch' as const },
        { name: 'XHR to unlisted domain', domain: 'unlisted-xhr.com', method: 'xhr' as const },
    ]

    for (const { name, domain, method } of casesWithoutHeaders) {
        test(`does NOT add tracing headers: ${name}`, async ({ page, context }) => {
            const headers = await setupAndTriggerRequest(page, context, { domain, method })

            expect(headers['x-posthog-distinct-id']).toBeUndefined()
            expect(headers['x-posthog-session-id']).toBeUndefined()
            expect(headers['x-posthog-window-id']).toBeUndefined()
        })
    }
})

import { existsSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

import packageJson from '../package.json'

const versionPath = fileURLToPath(new URL('../src/component/version.ts', import.meta.url))

export default function setupVersion(): () => void {
  const previousContents = existsSync(versionPath) ? readFileSync(versionPath, 'utf8') : undefined
  writeFileSync(versionPath, `export const version = '${packageJson.version}'\n`)

  return () => {
    if (previousContents === undefined) {
      rmSync(versionPath, { force: true })
    } else {
      writeFileSync(versionPath, previousContents)
    }
  }
}

import { ClientRateLimiter } from '../src/rate-limiter'

describe('ClientRateLimiter', () => {
    it('admits the burst, reports one transition, and refills fractionally', () => {
        let now = 0
        const limiter = new ClientRateLimiter(10, 100, () => now)

        for (let index = 0; index < 100; index++) {
            expect(limiter.consume()).toEqual({ allowed: true })
        }
        expect(limiter.consume()).toEqual({ allowed: false, reportDropped: 1 })
        limiter.reported()
        expect(limiter.consume()).toEqual({ allowed: false })

        now = 100
        expect(limiter.consume()).toEqual({ allowed: true })
        expect(limiter.consume()).toEqual({ allowed: false, reportDropped: 2 })
    })

    it('contains hostile and backward clocks', () => {
        let now = 1_000
        let throws = false
        const limiter = new ClientRateLimiter(1, 1, () => {
            if (throws) {
                throw new Error('clock failed')
            }
            return now
        })

        expect(limiter.consume()).toEqual({ allowed: true })
        now = 0
        expect(limiter.consume()).toMatchObject({ allowed: false })
        throws = true
        expect(() => limiter.consume()).not.toThrow()
    })
})

